#ifndef CAN_H
#define CAN_H

#include "Can_GeneralTypes.h"
#include "ComStack_Types.h"

#define CAN_VENDOR_ID        99U
#define CAN_MODULE_ID        80U
#define CAN_SW_MAJOR_VERSION 2U
#define CAN_SW_MINOR_VERSION 1U

typedef enum { CAN_CS_UNINIT = 0, CAN_CS_STARTED, CAN_CS_STOPPED, CAN_CS_SLEEP } Can_ControllerStateType;

void Can_Init(const Can_ConfigType* Config);
void Can_DeInit(void);
Std_ReturnType Can_SetControllerMode(uint8 Controller, Can_ControllerStateType Transition);
Can_ControllerStateType Can_GetControllerMode(uint8 Controller);
Std_ReturnType Can_Write(Can_HwHandleType Hth, const Can_PduType* PduInfo);
void Can_MainFunction_Write(void);
void Can_MainFunction_Read(void);
void Can_MainFunction_BusOff(void);
void Can_MainFunction_Wakeup(void);
void Can_MainFunction_Mode(void);

#endif /* CAN_H */

#include "Can.h"
#include "Can_Cfg.h"
#include "Det.h"
#include "SchM_Can.h"

static Can_ControllerStateType Can_ControllerState[CAN_CONTROLLER_COUNT];
static boolean Can_InitStatus = FALSE;

void Can_Init(const Can_ConfigType* Config) {
    uint8 ctrl;
    if (Config == NULL_PTR) {
        Det_ReportError(CAN_MODULE_ID, 0U, CAN_INIT_SID, CAN_E_PARAM_POINTER);
        return;
    }
    for (ctrl = 0U; ctrl < CAN_CONTROLLER_COUNT; ctrl++) {
        Can_ControllerState[ctrl] = CAN_CS_STOPPED;
        /* Initialize hardware registers */
        Can_Hw_Init(ctrl, &Config->ControllerConfig[ctrl]);
    }
    Can_InitStatus = TRUE;
}

void Can_DeInit(void) {
    uint8 ctrl;
    for (ctrl = 0U; ctrl < CAN_CONTROLLER_COUNT; ctrl++) {
        Can_Hw_DeInit(ctrl);
        Can_ControllerState[ctrl] = CAN_CS_UNINIT;
    }
    Can_InitStatus = FALSE;
}

Std_ReturnType Can_SetControllerMode(uint8 Controller, Can_ControllerStateType Transition) {
    if (!Can_InitStatus) {
        Det_ReportError(CAN_MODULE_ID, 0U, CAN_SETCONTROLLERMODE_SID, CAN_E_UNINIT);
        return E_NOT_OK;
    }
    if (Controller >= CAN_CONTROLLER_COUNT) {
        Det_ReportError(CAN_MODULE_ID, 0U, CAN_SETCONTROLLERMODE_SID, CAN_E_PARAM_CONTROLLER);
        return E_NOT_OK;
    }
    Can_ControllerState[Controller] = Transition;
    return Can_Hw_SetMode(Controller, Transition);
}

