#include "EcuM.h"
#include "Can.h"
#include "CanIf.h"
#include "Com.h"
#include "PduR.h"

void EcuM_Init(void) {
    /* Phase 1: MCU initialization */
    Mcu_Init(&Mcu_Config);
    Port_Init(&Port_Config);
    Dio_Init(&Dio_Config);

    /* Phase 2: Communication stack init (order matters!) */
    Can_Init(&Can_Config);
    CanIf_Init(&CanIf_Config);
    PduR_Init(&PduR_Config);
    Com_Init(&Com_Config);

    /* Phase 3: Start controllers */
    Can_SetControllerMode(CANIF_CTRL_CAN0, CAN_CS_STARTED);
    Can_SetControllerMode(CANIF_CTRL_CAN1, CAN_CS_STARTED);
    Can_SetControllerMode(CANIF_CTRL_CAN2, CAN_CS_STARTED);

    /* Phase 4: Enable PDU groups */
    Com_IpduGroupStart(COM_IPDU_GROUP_TX, TRUE);
    Com_IpduGroupStart(COM_IPDU_GROUP_RX, TRUE);
}
